cat > /tmp/verify.py <<'PYEOF'
import re, glob, subprocess, collections
REPO="/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
files=sorted(glob.glob("/tmp/main-ross/S0*/E*.md"))
problems=[]
seen=collections.defaultdict(list)
for f in files:
    t=open(f).read()
    m=re.match(r"^---\n(.*?)\n---\n\n(.*?)\n\n\*\*", t, re.S)
    if not m:
        problems.append(f"{f}: bad frontmatter/paragraph structure"); continue
    fm,par=m.group(1),m.group(2)
    sm=re.search(r'^summary: "(.*)"$', fm, re.M)
    if not sm: problems.append(f"{f}: missing summary")
    elif sm.group(1)!=par: problems.append(f"{f}: summary paragraph mismatch")
    for blk in re.findall(r"^\*\*(\w+)\*\* \((\S+)\)\n\nSource: friend/(\w+) @ ([0-9a-f]{40})\n\n(.*?)(?=\n\n\*\*|\Z)", t, re.S|re.M):
        who,ts,br,sha,text=blk
        seen[sha].append((f,who,br))
        if who.lower()!=br: problems.append(f"{f}: speaker {who} vs branch {br} ({sha[:8]})")
        if not text.startswith(who+":"): problems.append(f"{f}: text does not start with {who}: ({sha[:8]})")
    n=len(re.findall(r"^\*\*",t,re.M))
    if f.endswith(("E01.md",)) and False: pass
for sha,locs in seen.items():
    if len(locs)>1: problems.append(f"duplicate {sha[:8]}: {locs}")
# compare with all message shas
allsha=set(l.strip() for l in open("/tmp/allshas.txt"))
missing=allsha-set(seen)
if missing: problems.append(f"{len(missing)} message(s) not filed: {sorted(missing)[:5]}")
extra=set(seen)-allsha
if extra: problems.append(f"{len(extra)} filed shas not on branches: {sorted(extra)[:5]}")
print("\n".join(problems) if problems else "OK: %d files, %d entries"%(len(files),len(seen)))
PYEOF
python3 /tmp/verify.py
